let x = 5;
let y: i32 = 6;
let x = x + 1; // 섀도잉
println!("{} {}", x, y);

let mut count = 0;
count += 1;
println!("{}", count);

fn add(a: i32, b: i32) -> i32 {
    a + b
}

struct Point {
    x: i32,
    y: i32,
}
let p = Point { x: 1, y: 2 };
println!("{}", p.x + p.y);

enum Shape {
    Circle(f64),
    Rect { w: f64, h: f64 },
}
let s = Shape::Circle(1.0);
let _ = s;

struct Counter { n: u32 }
impl Counter {
    fn new() -> Self { Counter { n: 0 } }
    fn inc(&mut self) { self.n += 1; }
}

trait Speak {
    fn speak(&self) -> String;
}
struct Dog;
impl Speak for Dog {
    fn speak(&self) -> String { "멍".to_string() }
}

let n = 3;
let word = match n {
    1 => "하나",
    2 | 3 => "둘 또는 셋",
    _ => "그 외",
};
println!("{}", word);

let n = 5;
let label = if n > 3 { "큼" } else { "작음" };
let opt = Some(3);
if let Some(v) = opt {
    println!("{} {}", label, v);
}

let mut n = 0;
let result = loop {
    n += 1;
    if n == 3 {
        break n * 2;
    }
};
println!("{}", result);

let mut n = 3;
while n > 0 {
    n -= 1;
}

let mut sum = 0;
for i in 0..5 {
    sum += i;
}
println!("{}", sum);

let names = vec!["a", "b"];
for n in &names {
    println!("{}", n);
}

mod math {
    pub fn double(n: i32) -> i32 { n * 2 }
}
let d = math::double(4);
println!("{}", d);

pub struct User {
    pub name: String,
    age: u32,
}

fn first_even(v: &[i32]) -> Option<i32> {
    for &n in v {
        if n % 2 == 0 {
            return Some(n);
        }
    }
    None
}

async fn answer() -> u32 {
    42
}

